<section class="dashboard-hero"><span class="hero-icon"><i class="bi bi-shop"></i></span><div><p class="section-label">BOUCH</p><h2>Boucherie DAGRIL</h2><p>Réceptions sanitaires, transformation, DLC, coûts, ventes et transferts DECO.</p></div></section><?php if($success):?><div class="app-alert app-alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="app-alert app-alert-error"><?=e($error)?></div><?php endif;?><?php if(!empty($siteRequired)):?><div class="app-alert alert-info"><i class="bi bi-buildings"></i><span>Vue BOUCH en lecture. Sélectionnez le site BOUCH dans le sélecteur de site avant toute opération.</span></div><?php endif;?>
<div class="dashboard-grid dashboard-grid-2"><section class="form-panel"><h3>Réception interne BTR</h3><form method="post" action="<?=e(base_url('butchery/receipts'))?>" class="enterprise-form"><?=csrf_field()?><input type="hidden" name="source_type" value="internal_btr"><select name="livestock_transfer_id"><?php foreach($incoming as$x):?><option value="<?=$x['id']?>"><?=e($x['transfer_number'].' — '.$x['batch_number'].' — '.($x['source_unit']==='head'?$x['quantity_heads'].' têtes':$x['quantity_kg'].' kg'))?></option><?php endforeach;?></select><input type="datetime-local" name="received_at" required><input type="number" step="0.0001" name="unit_cost" placeholder="Coût unitaire"><button>Réceptionner BTR</button></form></section><section class="form-panel"><h3>Réception externe BRA</h3><form method="post" action="<?=e(base_url('butchery/receipts'))?>" class="enterprise-form"><?=csrf_field()?><input type="hidden" name="source_type" value="external_bra"><select name="supplier_id"><?php foreach($suppliers as$x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><input name="source_reference" placeholder="Référence fournisseur" required><input type="number" step="0.001" name="received_weight_kg" placeholder="Poids kg" required><input type="number" step="0.0001" name="unit_cost" placeholder="Coût/kg"><input type="datetime-local" name="received_at" required><button>Créer BRA</button></form></section></div>
<section class="table-panel"><h3>Contrôles sanitaires en attente</h3><table class="enterprise-table"><tbody><?php foreach($receipts as$r):?><tr><td><?=e($r['receipt_number'])?></td><td><?=e($r['supplier_name']?:$r['transfer_number'])?></td><td><?=e($r['received_unit']==='head'?$r['received_heads'].' têtes':$r['received_weight_kg'].' kg')?></td><td><form method="post" action="<?=e(base_url('butchery/receipts/'.$r['id'].'/control'))?>"><?=csrf_field()?><input type="number" step="0.1" name="temperature_c" placeholder="°C"><select name="visual_status"><option value="conform">Visuel conforme</option><option value="non_conform">Non conforme</option></select><select name="document_status"><option value="conform">Documents conformes</option><option value="non_conform">Non conformes</option></select><select name="decision"><option value="accept">Accepter</option><option value="reject">Refuser</option></select><select name="item_id"><?php foreach($items as$i):if(!in_array($i['item_kind'],['raw_material','additive']))continue;?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endforeach;?></select><input type="date" name="production_date" value="<?=date('Y-m-d')?>"><input type="date" name="expiry_date" required><input name="notes" placeholder="Observations"><button>Valider contrôle</button></form></td></tr><?php endforeach;?></tbody></table></section>
<section class="form-panel"><h3>Abattage des lots vivants réceptionnés</h3><form method="post" action="<?=e(base_url('butchery/slaughters'))?>" class="enterprise-form"><?=csrf_field()?><select name="live_lot_id"><?php foreach($live as$x):if($x['available_heads']<=0)continue;?><option value="<?=$x['id']?>"><?=e($x['lot_number'].' — '.$x['available_heads'].' têtes')?></option><?php endforeach;?></select><select name="raw_item_id"><?php foreach($items as$i):if($i['item_kind']==='raw_material'):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endif;endforeach;?></select><input type="number" name="input_heads" placeholder="Têtes"><input type="number" step="0.001" name="gross_weight_kg" placeholder="Poids brut kg"><input type="number" step="0.001" name="tare_weight_kg" placeholder="Tare kg"><input type="datetime-local" name="slaughtered_at"><button>Soumettre abattage</button></form><?php foreach($slaughters as$s):?><form method="post" action="<?=e(base_url('butchery/slaughters/'.$s['id'].'/validate'))?>"><?=csrf_field()?><?=e($s['slaughter_number'].' — '.$s['net_weight_kg'].' kg')?><input type="date" name="expiry_date" required><input type="number" step="0.0001" name="unit_cost" placeholder="Coût/kg"><button>Valider</button></form><?php endforeach;?></section>
<?php if(Auth::can('butchery','administer')):?><section class="form-panel"><h3>Nouvelle version de recette</h3><form method="post" action="<?=e(base_url('butchery/recipes'))?>" class="enterprise-form"><?=csrf_field()?><input name="code" placeholder="Code"><input name="name" placeholder="Nom"><select name="raw_item_id"><?php foreach($items as$i):if($i['item_kind']==='raw_material'):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endif;endforeach;?></select><button>Créer version</button></form></section><?php endif;?>
<section class="form-panel"><h3>Ordre de fabrication</h3><form method="post" action="<?=e(base_url('butchery/orders'))?>" class="enterprise-form"><?=csrf_field()?><select name="recipe_version_id"><?php foreach($recipes as$x):?><option value="<?=$x['id']?>"><?=e($x['code'].' v'.$x['version_number'])?></option><?php endforeach;?></select><select name="raw_lot_id"><?php foreach($raw as$x):if($x['status']==='available'):?><option value="<?=$x['id']?>"><?=e($x['lot_number'].' — '.$x['item_name'].' — '.$x['quantity_kg'].' kg — DLC '.$x['expiry_date'])?></option><?php endif;endforeach;?></select><input type="number" step="0.001" name="planned_input_kg" placeholder="Quantité planifiée"><input type="date" name="production_date"><button>Planifier OF</button></form><table class="enterprise-table"><tbody><?php foreach($orders as$o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['recipe_code'].' v'.$o['version_number'])?></td><td><?=e($o['status'])?></td><td><?php if($o['status']==='in_progress'):?><form method="post" action="<?=e(base_url('butchery/orders/'.$o['id'].'/results'))?>"><?=csrf_field()?><select name="raw_lot_id"><?php foreach($raw as$x):if($x['status']==='available'):?><option value="<?=$x['id']?>"><?=e($x['lot_number'])?></option><?php endif;endforeach;?></select><input name="raw_quantity_kg" type="number" step="0.001" placeholder="Matière kg"><select name="additive_item_id"><?php foreach($items as$i):if($i['item_kind']==='additive'):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endif;endforeach;?></select><input name="additive_quantity_kg" type="number" step="0.001" placeholder="Additif kg"><input name="additive_unit_cost" type="number" step="0.0001" placeholder="Coût additif"><select name="finished_item_id"><?php foreach($items as$i):if($i['item_kind']==='finished_product'):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endif;endforeach;?></select><input name="output_kg" type="number" step="0.001" placeholder="Produit kg"><select name="co_product_item_id"><?php foreach($items as$i):if($i['item_kind']==='co_product'):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endif;endforeach;?></select><input name="co_product_kg" type="number" step="0.001" placeholder="Coproduit kg"><input name="expiry_date" type="date"><input name="co_product_expiry_date" type="date"><input name="labor_cost" type="number" step="0.01" placeholder="Main-d’œuvre"><input name="energy_cost" type="number" step="0.01" placeholder="Énergie"><input name="allocated_cost" type="number" step="0.01" placeholder="Frais imputés"><button>Soumettre résultats</button></form><?php elseif($o['status']==='results_submitted'):?><form method="post" action="<?=e(base_url('butchery/orders/'.$o['id'].'/validate'))?>"><?=csrf_field()?><button>Valider OF</button></form><?php else:?>Rendement <?=e($o['yield_percent'])?>% — coût <?=e($o['cost_per_kg'])?>/kg<?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<section class="table-panel"><h3>Stocks et DLC</h3><table class="enterprise-table"><thead><tr><th>Lot</th><th>Produit</th><th>Quantité</th><th>DLC</th><th>Statut</th></tr></thead><tbody><?php foreach($finished as$x):?><tr><td><?=e($x['lot_number'])?></td><td><?=e($x['item_name'])?></td><td><?=e($x['quantity_kg'])?> kg</td><td><?=e($x['expiry_date'])?></td><td><?=e($x['status'])?></td></tr><?php endforeach;?></tbody></table></section>
<section class="form-panel"><h3>Vente directe ou transfert DECO</h3><form method="post" action="<?=e(base_url('butchery/sales'))?>"><?=csrf_field()?><select name="lot_type"><option value="raw">Matière sans transformation</option><option value="finished">Produit fini</option></select><input type="number" name="lot_id" placeholder="ID lot"><input type="number" step="0.001" name="quantity_kg" placeholder="kg"><input name="customer_name" placeholder="Client"><input type="number" step="0.01" name="unit_price" placeholder="Prix"><button>Vendre</button></form><form method="post" action="<?=e(base_url('butchery/transfers'))?>"><?=csrf_field()?><select name="finished_lot_id"><?php foreach($finished as$x):if($x['status']==='available'):?><option value="<?=$x['id']?>"><?=e($x['lot_number'].' — '.$x['quantity_kg'].' kg')?></option><?php endif;endforeach;?></select><input name="quantity_kg" type="number" step="0.001" placeholder="kg"><button>Créer BTR DECO</button></form><?php foreach($transfers as$t):?><?=e($t['transfer_number'].' — '.$t['status'])?> <?php if($t['status']==='draft'):?><form method="post" action="<?=e(base_url('butchery/transfers/'.$t['id'].'/approve'))?>"><?=csrf_field()?><button>Valider</button></form><?php elseif($t['status']==='approved'):?><form method="post" action="<?=e(base_url('butchery/transfers/'.$t['id'].'/dispatch'))?>"><?=csrf_field()?><button>Expédier</button></form><?php endif;endforeach;?></section>
